import { useCallback, useRef, useState } from "react";

type UseCopyOptions = {
  timeout?: number;
};

export const useCopy = ({ timeout = 2000 }: UseCopyOptions = {}) => {
  const [copied, setCopied] = useState<string | null>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const copy = useCallback(
    async (value: string) => {
      try {
        await navigator.clipboard.writeText(value);
        setCopied(value);

        // Clear any existing timeout
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }

        // Set new timeout to clear copied state
        timeoutRef.current = setTimeout(() => {
          setCopied(null);
        }, timeout);
      } catch (error) {
        console.error("Failed to copy to clipboard:", error);
        setCopied(null);
      }
    },
    [timeout],
  );

  const isCopied = copied !== null;

  return { copy, copied, isCopied };
};

import { useCallback, useEffect, useMemo, useState } from "react";

const useLoop = (array: string[], delay = 3000) => {
  const [key, setKey] = useState(0);

  const incrementKey = useCallback(() => {
    setKey((prev) => prev + 1);
  }, []);

  const currentItem = useMemo(() => {
    return array[key % array.length];
  }, [array, key]);

  useEffect(() => {
    const interval = setInterval(incrementKey, delay);
    return () => clearInterval(interval);
  }, [delay, incrementKey]);

  return { currentItem, key };
};

export { useLoop };

import { useCallback, useEffect, useState } from "react";

export const useMeasure = <T extends HTMLElement = HTMLElement>(): [
  (node: T | null) => void,
  { width: number; height: number },
] => {
  const [element, setElement] = useState<T | null>(null);
  const [bounds, setBounds] = useState({ width: 0, height: 0 });

  const ref = useCallback((node: T | null) => {
    setElement(node);
  }, []);

  useEffect(() => {
    if (!element) return;

    const observer = new ResizeObserver(([entry]) => {
      setBounds({
        width: entry.contentRect.width,
        height: entry.contentRect.height,
      });
    });

    observer.observe(element);
    return () => observer.disconnect();
  }, [element]);

  return [ref, bounds];
};

import { useEffect, useState } from "react";

const MOBILE_BREAKPOINT = 768;

export const useIsMobile = () => {
  const [isMobile, setIsMobile] = useState<boolean | undefined>(undefined);

  useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    };
    mql.addEventListener("change", onChange);
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    return () => mql.removeEventListener("change", onChange);
  }, []);

  return !!isMobile;
};

import type { ChatMessage, ChatStatus, FilePart } from "@intentface/chat/types";
import type * as sdk from "ai";

export type AppUIMessage = sdk.UIMessage<{
  stopped?: boolean;
}>;

// The ask-user contract lives in the headless package; this app consumes it
// from here so UI code has a single import boundary.
export type { AskUserInput, AskUserOption, AskUserQuestion } from "@intentface/chat/types";

// ---------------------------------------------------------------------------
// Assignability locks
//
// @intentface/chat owns structural message types that AI SDK shapes must keep
// satisfying. These asserts fail typecheck loudly if an `ai` upgrade (or a
// package change) breaks that structural compatibility.
// ---------------------------------------------------------------------------

type Assert<T extends true> = T;

export type MessageContractCheck = Assert<
  AppUIMessage extends ChatMessage<{ stopped?: boolean }> ? true : false
>;

export type FilePartContractCheck = Assert<sdk.FileUIPart extends FilePart ? true : false>;

export type ChatStatusContractCheck = Assert<sdk.ChatStatus extends ChatStatus ? true : false>;

"use client";

import { Chip as ChipPrimitive } from "@intentface/chat/chip";
import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";
import HoverCard from "@/components/ui/hover-card";
import { cn } from "@/lib/utils";

// Shared inline text-flow surface for committed chips and the composer's
// active-prefix decoration — one model so both sit on the same baseline/line box.
// `inline` (not inline-flex) so the chip flows as text; `py` is visual only and
// doesn't grow the line box; `box-decoration-clone` keeps padding/bg intact if a
// chip wraps; `leading-[inherit]` so it never inflates the editor's line height.
export const CHIP_SURFACE_CLASS =
  "box-decoration-clone inline rounded-sm px-0.75 py-0.5 align-baseline font-[450] leading-[inherit] whitespace-nowrap";

const chipVariants = cva(CHIP_SURFACE_CLASS, {
  variants: {
    variant: {
      primary: "bg-primary-hover text-ink-primary",
      accent: "bg-accent text-accent-ink",
      warning: "bg-warning text-warning-ink",
    },
  },
  defaultVariants: {
    variant: "primary",
  },
});

export type ChipVariant = NonNullable<VariantProps<typeof chipVariants>["variant"]>;

// Inline-block icon with a baseline nudge (not flex/absolute) so it rides the
// text baseline without inflating the line box. The -0.2em nudge is a starting
// point — tune against the editor's line-height.
const CHIP_ICON_WRAPPER_CLASSES =
  "mr-0.5 inline-block size-4 align-[-0.2em] text-ink-tertiary [&>svg]:block [&>svg]:size-4";

type ChipRootProps = Omit<ComponentProps<typeof ChipPrimitive>, "variant"> & {
  variant?: ChipVariant;
};

const ChipRoot = ({ variant, className, ...props }: ChipRootProps) => (
  <ChipPrimitive
    variant={variant}
    className={cn(chipVariants({ variant }), className)}
    renderWithPreview={(badge, preview) => (
      <HoverCard>
        <HoverCard.Trigger render={badge} />
        <HoverCard.Content>{preview}</HoverCard.Content>
      </HoverCard>
    )}
    {...props}
  />
);

type ChipIconProps = ComponentProps<typeof ChipPrimitive.Icon>;

const ChipIcon = ({ className, ...props }: ChipIconProps) => (
  <ChipPrimitive.Icon className={cn(CHIP_ICON_WRAPPER_CLASSES, className)} {...props} />
);

export const Chip = Object.assign(ChipRoot, {
  Icon: ChipIcon,
  Label: ChipPrimitive.Label,
  Preview: ChipPrimitive.Preview,
});

