"use client";

import type { ToolLabels } from "@intentface/chat/message-utils";
import type { ToolPart } from "@intentface/chat/types";
import { CircleHelpIcon, CircleIcon } from "lucide-react";
import {
  Children,
  type ComponentProps,
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";
import { CheckMarkMediumIcon } from "@/components/icons/check-mark-medium";
import { ChevronDownIcon } from "@/components/icons/chevron-down";
import { Collapsible } from "@/components/ui/collapsible";
import { Markdown } from "@/components/ui/markdown";
import { DEFAULT_TOOL_LABELS } from "@/lib/ai/tool-labels";
import type { AskUserInput, AskUserQuestion } from "@/lib/ai/types";
import { cn } from "@/lib/utils";

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------

type StepsContextValue = {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  toolLabels: ToolLabels;
};

const StepsContext = createContext<StepsContextValue | null>(null);

const useSteps = () => {
  const context = useContext(StepsContext);
  if (!context) {
    throw new Error("Steps components must be used within Steps");
  }
  return context;
};

// ---------------------------------------------------------------------------
// Root
// ---------------------------------------------------------------------------

type StepsRootProps = Omit<ComponentProps<"div">, "defaultOpen"> & {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  toolLabels?: ToolLabels;
};

const StepsRoot = ({
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  toolLabels = DEFAULT_TOOL_LABELS,
  className,
  children,
  ...props
}: StepsRootProps) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isControlled = controlledOpen !== undefined;
  const isOpen = isControlled ? controlledOpen : internalOpen;

  const setIsOpen = useCallback(
    (value: boolean) => {
      if (!isControlled) setInternalOpen(value);
      onOpenChange?.(value);
    },
    [isControlled, onOpenChange],
  );

  const contextValue = useMemo(
    () => ({ isOpen, setIsOpen, toolLabels }),
    [isOpen, setIsOpen, toolLabels],
  );

  return (
    <StepsContext.Provider value={contextValue}>
      <Collapsible
        open={isOpen}
        onOpenChange={(open) => setIsOpen(open)}
        data-slot="steps"
        className={cn("not-prose w-full", className)}
        {...props}
      >
        {children}
      </Collapsible>
    </StepsContext.Provider>
  );
};

StepsRoot.displayName = "Steps";

// ---------------------------------------------------------------------------
// Header (trigger for outer collapsible)
// ---------------------------------------------------------------------------

type StepsHeaderProps = ComponentProps<typeof Collapsible.Trigger>;

const StepsHeader = ({ children, className, ...props }: StepsHeaderProps) => {
  const { isOpen } = useSteps();

  return (
    <Collapsible.Trigger
      className={cn(
        "flex w-full cursor-pointer items-center gap-2 py-1 text-sm text-ink-secondary transition-colors hover:text-ink-primary",
        className,
      )}
      {...props}
    >
      {children ?? "Steps"}
      <ChevronDownIcon
        className={cn("size-4 shrink-0 transition-transform", isOpen ? "rotate-180" : "rotate-0")}
      />
    </Collapsible.Trigger>
  );
};

StepsHeader.displayName = "StepsHeader";

// ---------------------------------------------------------------------------
// Content (panel for outer collapsible — timeline container)
// ---------------------------------------------------------------------------

type StepsContentProps = ComponentProps<typeof Collapsible.Panel>;

const StepsContent = ({ className, children, ...props }: StepsContentProps) => (
  <Collapsible.Panel className={cn("mt-2", className)} {...props}>
    <div className="flex flex-col [&>:last-child_[data-slot=step-connector]]:hidden">
      {children}
    </div>
  </Collapsible.Panel>
);

StepsContent.displayName = "StepsContent";

// ---------------------------------------------------------------------------
// Step — collapsible timeline item
//
// When children are present the label becomes a collapsible trigger and the
// children render below with a vertical connector line on the left. When
// there are no children the step is a static row (no collapse).
// ---------------------------------------------------------------------------

type StepStatus = "complete" | "active" | "pending";

type IconComponent = React.ComponentType<{ className?: string }>;

const statusIcons: Record<StepStatus, IconComponent> = {
  complete: CheckMarkMediumIcon,
  active: CircleIcon,
  pending: CircleIcon,
};

type StepsStepProps = {
  label: string;
  status?: StepStatus;
  icon?: IconComponent;
  className?: string;
  children?: ReactNode;
};

const StepsStep = ({ label, status = "complete", icon, className, children }: StepsStepProps) => {
  const Icon = icon ?? statusIcons[status];
  const hasContent = Children.toArray(children).length > 0;

  const iconClasses = cn(
    status === "complete" && "text-ink-secondary",
    status === "active" && "text-ink-primary",
    status === "pending" && "text-slate-9",
  );

  const labelClasses = cn(
    "text-sm text-left",
    status === "active" && "text-ink-primary font-medium",
    status === "complete" && "text-ink-secondary",
    status === "pending" && "text-slate-9",
  );

  const connector = (
    <div data-slot="step-connector" className="flex">
      <div className="flex w-4 justify-center">
        <div className="h-3 w-px bg-slate-6" />
      </div>
    </div>
  );

  // Static row — no children, not collapsible
  if (!hasContent) {
    return (
      <div data-slot="steps-step" data-status={status} className={className}>
        <div className="flex items-center gap-2 py-0.5">
          <div className={cn("flex size-4 shrink-0 items-center justify-center", iconClasses)}>
            <Icon className={cn("size-3.5", status === "active" && "animate-pulse")} />
          </div>
          <span className={labelClasses}>{label}</span>
        </div>
        {connector}
      </div>
    );
  }

  // Collapsible row — trigger swaps icon ↔ chevron on hover/open
  return (
    <Collapsible
      defaultOpen={status === "active"}
      data-slot="steps-step"
      data-status={status}
      className={className}
    >
      <Collapsible.Trigger className="group/trigger flex w-full cursor-pointer items-center gap-2 py-0.5 transition-colors hover:text-ink-primary">
        <div
          className={cn("relative flex size-4 shrink-0 items-center justify-center", iconClasses)}
        >
          {/* Status icon — hides on hover and when panel is open */}
          <span className="transition-opacity group-hover/trigger:opacity-0 group-data-[panel-open]/trigger:opacity-0">
            <Icon className={cn("size-3.5", status === "active" && "animate-pulse")} />
          </span>
          {/* Chevron — appears on hover, stays visible when open, rotates 180° */}
          <ChevronDownIcon
            className={cn(
              "absolute size-4 opacity-0 transition-all",
              "group-hover/trigger:opacity-100",
              "group-data-panel-open/trigger:opacity-100",
              "group-data-panel-open/trigger:rotate-180",
            )}
          />
        </div>
        <span className={labelClasses}>{label}</span>
      </Collapsible.Trigger>

      <Collapsible.Panel>
        <div className="flex gap-2">
          <div className="flex w-4 justify-center">
            <div className="w-px bg-slate-6" />
          </div>
          <div className="min-w-0 flex-1 py-1">{children}</div>
        </div>
      </Collapsible.Panel>

      {connector}
    </Collapsible>
  );
};

StepsStep.displayName = "StepsStep";

// ---------------------------------------------------------------------------
// Body — markdown content inside a step's collapsible area
// ---------------------------------------------------------------------------

type StepsBodyProps = ComponentProps<typeof Markdown>;

const StepsBody = ({ className, children, ...props }: StepsBodyProps) => (
  <Markdown
    className={cn("text-sm leading-tight text-ink-secondary [&_p]:mb-0", className)}
    {...props}
  >
    {children}
  </Markdown>
);

StepsBody.displayName = "StepsBody";

// ---------------------------------------------------------------------------
// Summary (compact result text)
// ---------------------------------------------------------------------------

type StepsSummaryProps = ComponentProps<"span">;

const StepsSummary = ({ className, children, ...props }: StepsSummaryProps) => (
  <span
    data-slot="steps-summary"
    className={cn("text-xs text-ink-secondary", className)}
    {...props}
  >
    {children}
  </span>
);

StepsSummary.displayName = "StepsSummary";

// ---------------------------------------------------------------------------
// SearchResults / SearchResult
// ---------------------------------------------------------------------------

type StepsSearchResultsProps = ComponentProps<"div">;

const StepsSearchResults = ({ className, children, ...props }: StepsSearchResultsProps) => (
  <div
    data-slot="steps-search-results"
    className={cn("flex flex-wrap gap-1.5", className)}
    {...props}
  >
    {children}
  </div>
);

StepsSearchResults.displayName = "StepsSearchResults";

type StepsSearchResultProps = ComponentProps<"span">;

const StepsSearchResult = ({ className, children, ...props }: StepsSearchResultProps) => (
  <span
    data-slot="steps-search-result"
    className={cn(
      "inline-flex items-center rounded-md border border-border bg-muted px-2 py-0.5 text-xs text-muted-foreground",
      className,
    )}
    {...props}
  >
    {children}
  </span>
);

StepsSearchResult.displayName = "StepsSearchResult";

// ---------------------------------------------------------------------------
// ToolCall — renders a tool invocation as a timeline step
// ---------------------------------------------------------------------------

type WebSearchFinding = {
  claim: string;
  sources: { url: string; title: string }[];
};

type StepsToolCallProps = {
  part: ToolPart;
  className?: string;
};

const StepsToolCall = ({ part, className }: StepsToolCallProps) => {
  const { toolLabels } = useSteps();
  const input = (part.input as Record<string, unknown>) ?? {};
  const isActive = part.state === "input-streaming" || part.state === "input-available";
  const isComplete = part.state === "output-available";
  const name = part.type.replace("tool-", "");

  const labelConfig = toolLabels[name];
  const label = labelConfig
    ? isActive
      ? labelConfig.active(input)
      : labelConfig.complete(input)
    : isActive
      ? `Running ${name}`
      : `Ran ${name}`;

  const status: StepStatus = isActive ? "active" : isComplete ? "complete" : "pending";

  // Extract summary from tool output
  const output = isComplete ? (part.output as Record<string, unknown>) : null;
  const summary = typeof output?.summary === "string" ? output.summary : null;

  // Flatten sources from web search findings
  const rawOutput = isComplete && part.type === "tool-webSearch" ? part.output : null;
  const findings = Array.isArray(rawOutput) ? (rawOutput as WebSearchFinding[]) : [];
  const sources = findings
    .flatMap((f) => f.sources)
    .map((s) => {
      try {
        return { ...s, domain: new URL(s.url).hostname.replace(/^www\./, "") };
      } catch {
        return { ...s, domain: s.title };
      }
    });

  return (
    <StepsStep label={label} status={status} className={className}>
      {summary && <StepsSummary>{summary}</StepsSummary>}
      {sources.length > 0 && (
        <StepsSearchResults>
          {sources.map((source, index) => (
            <StepsSearchResult key={index}>{source.domain}</StepsSearchResult>
          ))}
        </StepsSearchResults>
      )}
    </StepsStep>
  );
};

StepsToolCall.displayName = "StepsToolCall";

// ---------------------------------------------------------------------------
// AskUser — renders an answered ask-user exchange as a timeline step
// ---------------------------------------------------------------------------

type StepsAskUserProps = {
  part: ToolPart;
  className?: string;
};

const StepsAskUser = ({ part, className }: StepsAskUserProps) => {
  const isComplete = part.state === "output-available";
  const input = part.input as AskUserInput | undefined;
  const questions: AskUserQuestion[] = input?.questions ?? [];

  let answers: Record<string, string> = {};
  if (isComplete) {
    try {
      answers = JSON.parse(part.output as string) as Record<string, string>;
    } catch (error) {
      console.error("Failed to parse askUser output", {
        output: part.output,
        error,
      });
    }
  }

  const count = questions.length;
  const label = `Answered ${count} ${count === 1 ? "question" : "questions"}`;

  return (
    <StepsStep
      label={label}
      status={isComplete ? "complete" : "active"}
      icon={CircleHelpIcon}
      className={className}
    >
      <div className="flex flex-col gap-1.5">
        {questions.map((q) => (
          <div key={q.question} className="flex flex-col gap-0.5">
            <span className="text-xs font-medium leading-tight text-ink-primary">{q.question}</span>
            {isComplete && (
              <span className="text-xs leading-tight text-ink-secondary">
                {answers[q.question] ?? "—"}
              </span>
            )}
          </div>
        ))}
      </div>
    </StepsStep>
  );
};

StepsAskUser.displayName = "StepsAskUser";

// ---------------------------------------------------------------------------
// Compound export
// ---------------------------------------------------------------------------

export const Steps = Object.assign(StepsRoot, {
  Header: StepsHeader,
  Content: StepsContent,
  Step: StepsStep,
  Body: StepsBody,
  ToolCall: StepsToolCall,
  AskUser: StepsAskUser,
  Summary: StepsSummary,
  SearchResults: StepsSearchResults,
  SearchResult: StepsSearchResult,
});

"use client";

import { splitReasoningByHeaders } from "@intentface/chat/message-utils";
import { AnimatePresence, motion } from "motion/react";
import {
  type ComponentProps,
  createContext,
  memo,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { ChevronDownIcon } from "@/components/icons/chevron-down";
import { Collapsible } from "@/components/ui/collapsible";
import { Markdown } from "@/components/ui/markdown";
import { cn } from "@/lib/utils";
import { BrainIcon } from "../icons/brain";
import { TextShimmer } from "../ui/text-shimmer";

const MS_IN_S = 1000;

type ReasoningContextValue = {
  isStreaming: boolean;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  duration: number | undefined;
};

const ReasoningContext = createContext<ReasoningContextValue | null>(null);

export const useReasoning = () => {
  const context = useContext(ReasoningContext);
  if (!context) {
    throw new Error("Reasoning components must be used within Reasoning");
  }
  return context;
};

export type ReasoningRootProps = Omit<ComponentProps<typeof Collapsible>, "onOpenChange"> & {
  isStreaming?: boolean;
  duration?: number;
  onOpenChange?: (open: boolean) => void;
};

const ReasoningRoot = memo(
  ({
    isStreaming = false,
    open: controlledOpen,
    defaultOpen,
    onOpenChange,
    duration: durationProp,
    className,
    children,
    ...props
  }: ReasoningRootProps) => {
    const resolvedDefaultOpen = defaultOpen ?? false;

    const [internalOpen, setInternalOpen] = useState(resolvedDefaultOpen);
    const isControlled = controlledOpen !== undefined;
    const isOpen = isControlled ? controlledOpen : internalOpen;

    const [duration, setDuration] = useState<number | undefined>(durationProp);
    const hasEverStreamedRef = useRef(isStreaming);
    const startTimeRef = useRef<number | null>(null);

    const setIsOpen = useCallback(
      (value: boolean) => {
        if (!isControlled) {
          setInternalOpen(value);
        }
        onOpenChange?.(value);
      },
      [isControlled, onOpenChange],
    );

    // Track when streaming starts and compute duration
    useEffect(() => {
      if (isStreaming) {
        hasEverStreamedRef.current = true;
        if (startTimeRef.current === null) {
          startTimeRef.current = Date.now();
        }
      } else if (startTimeRef.current !== null) {
        setDuration(Math.ceil((Date.now() - startTimeRef.current) / MS_IN_S));
        startTimeRef.current = null;
      }
    }, [isStreaming]);

    const contextValue = useMemo(
      () => ({ duration, isOpen, isStreaming, setIsOpen }),
      [duration, isOpen, isStreaming, setIsOpen],
    );

    return (
      <ReasoningContext.Provider value={contextValue}>
        <Collapsible
          open={isOpen}
          onOpenChange={(open) => setIsOpen(open)}
          data-slot="reasoning"
          data-streaming={isStreaming ? "" : undefined}
          className={cn("not-prose w-full", className)}
          {...props}
        >
          {children}
        </Collapsible>
      </ReasoningContext.Provider>
    );
  },
);

ReasoningRoot.displayName = "Reasoning";

export type ReasoningTriggerProps = ComponentProps<typeof Collapsible.Trigger> & {
  label?: string[];
  getThinkingMessage?: (
    isStreaming: boolean,
    duration?: number,
    label?: string,
  ) => { key: string; component: ReactNode };
};

const defaultGetThinkingMessage = (
  isStreaming: boolean,
  duration?: number,
  label?: string,
): { key: string; component: ReactNode } => {
  if (isStreaming || duration === 0) {
    if (isStreaming && label) {
      return {
        key: `header-${label}`,
        component: <TextShimmer>{label}</TextShimmer>,
      };
    }
    return {
      key: "thinking",
      component: <TextShimmer>Thinking...</TextShimmer>,
    };
  }

  return {
    key: "thought",
    component: <span>Thought for {duration ?? "a few"} seconds</span>,
  };
};

const ReasoningTrigger = memo(
  ({
    label,
    getThinkingMessage = defaultGetThinkingMessage,
    className,
    children,
    ...props
  }: ReasoningTriggerProps) => {
    const { isStreaming, isOpen, duration } = useReasoning();
    const activeLabel = label?.at(-1);

    const { key, component } = getThinkingMessage(isStreaming, duration, activeLabel);
    return (
      <Collapsible.Trigger
        className={cn(
          "flex cursor-pointer w-full text-sm items-center gap-2 text-ink-secondary rounded-md transition-colors hover:text-ink-primary",
          className,
        )}
        {...props}
      >
        {children ?? (
          <>
            <div className="flex items-center gap-1">
              <BrainIcon className="size-4" />
              <AnimatePresence mode="popLayout" initial={false}>
                <motion.span
                  key={key}
                  initial={{ opacity: 0, y: "100%", filter: "blur(4px)" }}
                  animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                  exit={{ opacity: 0, y: "-100%", filter: "blur(4px)" }}
                  transition={{ duration: 0.3, ease: "easeOut" }}
                  className="whitespace-nowrap text-gray-11/60"
                >
                  {component}
                </motion.span>
              </AnimatePresence>
            </div>
            <ChevronDownIcon
              className={cn("size-5 transition-transform", isOpen ? "rotate-180" : "rotate-0")}
            />
          </>
        )}
      </Collapsible.Trigger>
    );
  },
);

ReasoningTrigger.displayName = "ReasoningTrigger";

export type ReasoningContentProps = Omit<ComponentProps<typeof Collapsible.Panel>, "children"> & {
  children: string | string[];
};

const ReasoningContent = ({ children, className, ...props }: ReasoningContentProps) => {
  const texts = Array.isArray(children) ? children : [children];
  const sections = splitReasoningByHeaders(texts);

  return (
    <Collapsible.Panel className={cn("text-sm", className)} {...props}>
      <div className="flex flex-col gap-3 p-2">
        {sections.map((section, i) => (
          <div key={i} className="flex flex-col gap-1">
            {section.header && (
              <span className="text-sm font-medium text-ink-primary">{section.header}</span>
            )}
            {section.body && (
              <Markdown className="text-ink-secondary text-sm [&_p]:mb-0">{section.body}</Markdown>
            )}
          </div>
        ))}
      </div>
    </Collapsible.Panel>
  );
};

export const Reasoning = Object.assign(ReasoningRoot, {
  Trigger: ReasoningTrigger,
  Content: ReasoningContent,
});

"use client";

import { AnimatePresence, motion } from "motion/react";
import { Children, type ComponentProps, useCallback, useState } from "react";
import { TextShimmer } from "@/components/ui/text-shimmer";
import { cn } from "@/lib/utils";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const ITEM_HEIGHT = 20; // h-5
const ITEM_GAP = 8; // gap-2
const MAX_VISIBLE = 5;
const MAX_HEIGHT = MAX_VISIBLE * ITEM_HEIGHT + (MAX_VISIBLE - 1) * ITEM_GAP;

// ---------------------------------------------------------------------------
// Root
//
// Always renders all children. Single motion.div container animates height
// between one item (collapsed) and full content (expanded, capped).
// `justify-end` keeps the last item visible when collapsed.
// ---------------------------------------------------------------------------

type StepQueueRootProps = ComponentProps<"div"> & {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
};

const StepQueueRoot = ({
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  className,
  children,
  ...props
}: StepQueueRootProps) => {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isControlled = controlledOpen !== undefined;
  const isOpen = isControlled ? controlledOpen : internalOpen;
  const childCount = Children.count(children);
  const shouldUseMask = childCount > 1;

  const toggle = useCallback(() => {
    const next = !isOpen;
    if (!isControlled) setInternalOpen(next);
    onOpenChange?.(next);
  }, [isOpen, isControlled, onOpenChange]);

  return (
    <div
      role="button"
      tabIndex={0}
      data-slot="step-queue"
      data-open={isOpen || undefined}
      onClick={toggle}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          toggle();
        }
      }}
      className={cn(
        "not-prose relative w-full cursor-pointer p-3",
        shouldUseMask &&
          "mask-[linear-gradient(to_bottom,transparent,black_24px,black_calc(100%-24px),transparent)]",
        className,
      )}
      {...props}
    >
      <div
        className="relative flex flex-col justify-end gap-2"
        style={{ maxHeight: MAX_HEIGHT, height: isOpen ? "auto" : ITEM_HEIGHT }}
      >
        <AnimatePresence mode="popLayout" initial={false}>
          {children}
        </AnimatePresence>
      </div>
    </div>
  );
};

StepQueueRoot.displayName = "StepQueue";

// ---------------------------------------------------------------------------
// Item — animated wrapper for a single step
// ---------------------------------------------------------------------------

type StepQueueItemProps = ComponentProps<typeof motion.div>;

const StepQueueItem = ({ className, children, ...props }: StepQueueItemProps) => {
  return (
    <motion.div
      data-slot="step-queue-item"
      initial={{ height: 0 }}
      animate={{ height: ITEM_HEIGHT }}
      exit={{ height: 0 }}
      transition={{
        duration: 0.2,
        type: "spring",
        bounce: 0,
      }}
      className={cn("flex shrink-0 items-center text-sm font-medium text-ink-secondary", className)}
      {...props}
    >
      <motion.div
        initial={{ opacity: 0, y: ITEM_HEIGHT, filter: "blur(8px)" }}
        animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
        exit={{ opacity: 0, y: -ITEM_HEIGHT, filter: "blur(8px)" }}
        transition={{ duration: 0.2, type: "spring", bounce: 0 }}
        className="flex shrink-0 items-center gap-2"
      >
        {children}
      </motion.div>
    </motion.div>
  );
};

StepQueueItem.displayName = "StepQueueItem";

// ---------------------------------------------------------------------------
// Icon — renders inside an Item, swaps between a custom icon and a default
// ---------------------------------------------------------------------------

type StepQueueIconProps = ComponentProps<"span">;

const StepQueueIcon = ({ className, children, ...props }: StepQueueIconProps) => {
  return (
    <span
      data-slot="step-queue-icon"
      className={cn("flex shrink-0 items-center justify-center", className)}
      {...props}
    >
      {children}
    </span>
  );
};

StepQueueIcon.displayName = "StepQueueIcon";

// ---------------------------------------------------------------------------
// Label — text content inside an Item, shimmer when active
// ---------------------------------------------------------------------------

type StepQueueLabelProps = ComponentProps<"span"> & {
  active?: boolean;
};

const StepQueueLabel = ({ active = false, className, children, ...props }: StepQueueLabelProps) => {
  return (
    <span
      data-slot="step-queue-label"
      className={cn("min-w-0 flex-1 truncate", className)}
      {...props}
    >
      {active ? <TextShimmer>{children}</TextShimmer> : children}
    </span>
  );
};

StepQueueLabel.displayName = "StepQueueLabel";

// ---------------------------------------------------------------------------
// Compound export
// ---------------------------------------------------------------------------

export const StepQueue = Object.assign(StepQueueRoot, {
  Item: StepQueueItem,
  Icon: StepQueueIcon,
  Label: StepQueueLabel,
});

