"use client";

import { XIcon } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import type { ComponentProps, ReactNode } from "react";
import { CheckMarkMediumIcon } from "@/components/icons/check-mark-medium";
import { CopyIcon } from "@/components/icons/copy";
import { IconButton } from "@/components/ui/icon-button";
import { Markdown } from "@/components/ui/markdown";
import Tooltip from "@/components/ui/tooltip";
import { useCopy } from "@/hooks/use-copy";
import { cn } from "@/lib/utils";

type ArtifactsPanelRootProps = {
  open: boolean;
  children?: ReactNode;
  className?: string;
};

const ArtifactsPanelRoot = ({ open, children, className, ...props }: ArtifactsPanelRootProps) => (
  <AnimatePresence>
    {open && (
      <motion.aside
        data-slot="artifacts-panel"
        initial={{ width: 0, opacity: 0 }}
        animate={{ width: "var(--artifacts-panel-width)", opacity: 1 }}
        exit={{ width: 0, opacity: 0 }}
        transition={{ duration: 0.2, ease: "easeInOut" }}
        className={cn(
          "relative h-full shrink-0 overflow-hidden border-l border-border bg-background",
          className,
        )}
        {...props}
      >
        <div className="flex h-full w-(--artifacts-panel-width) flex-col">{children}</div>
      </motion.aside>
    )}
  </AnimatePresence>
);

const ArtifactsPanelContent = ({ className, ...props }: ComponentProps<typeof Markdown>) => (
  <Markdown className={cn("size-full", className)} {...props} />
);

const ArtifactsPanelHeader = ({
  title,
  onClose,
  className,
  ...props
}: ComponentProps<"div"> & {
  title: string;
  onClose: () => void;
}) => (
  <div
    data-slot="artifacts-panel-header"
    className={cn("flex items-center justify-between border-b border-border px-4 py-3", className)}
    {...props}
  >
    <h2 className="truncate text-sm font-semibold">{title}</h2>
    <IconButton variant="ghost" size="sm" onClick={onClose}>
      <XIcon />
    </IconButton>
  </div>
);

const ArtifactsPanelFooter = ({
  content,
  className,
  ...props
}: ComponentProps<"div"> & { content: string }) => {
  const { copy, isCopied } = useCopy();

  return (
    <div
      data-slot="artifacts-panel-footer"
      className={cn("flex items-center justify-end border-t border-border px-4 py-2", className)}
      {...props}
    >
      <Tooltip.Provider>
        <Tooltip>
          <Tooltip.Trigger
            render={
              <IconButton variant="ghost" size="sm" onClick={() => copy(content)}>
                {isCopied ? <CheckMarkMediumIcon /> : <CopyIcon />}
              </IconButton>
            }
          />
          <Tooltip.Content>{isCopied ? "Copied!" : "Copy markdown"}</Tooltip.Content>
        </Tooltip>
      </Tooltip.Provider>
    </div>
  );
};

const ArtifactsPanelViewport = ({ className, ...props }: ComponentProps<"div">) => (
  <div
    data-slot="artifacts-panel-viewport"
    className={cn("flex-1 overflow-y-auto p-4", className)}
    {...props}
  />
);

export const ArtifactsPanel = Object.assign(ArtifactsPanelRoot, {
  Header: ArtifactsPanelHeader,
  Viewport: ArtifactsPanelViewport,
  Content: ArtifactsPanelContent,
  Footer: ArtifactsPanelFooter,
});

"use client";

import { useState } from "react";
import { Composer } from "@/components/ai/composer";
import { Message } from "@/components/ai/message";
import { Thread } from "@/components/ai/thread";

type DemoMessage = {
  id: string;
  role: "user" | "assistant";
  text: string;
};

export const IntentfaceChatDemo = () => {
  const [messages, setMessages] = useState<DemoMessage[]>([
    {
      id: "welcome",
      role: "assistant",
      text: "Ask a question to try the installed Intentface chat primitives.",
    },
  ]);

  return (
    <div className="h-[640px] rounded-lg border border-primary-border bg-secondary">
      <Thread>
        <Thread.Overlay direction="top" />
        <Thread.Viewport>
          {messages.map((message, index) => (
            <Message
              key={message.id}
              role={message.role}
              isLast={index === messages.length - 1}
              isError={false}
            >
              <Message.Content>
                {message.role === "user" ? (
                  <Message.Text>{message.text}</Message.Text>
                ) : (
                  <Message.Markdown>{message.text}</Message.Markdown>
                )}
              </Message.Content>
            </Message>
          ))}
        </Thread.Viewport>
        <Thread.Composer>
          <Composer
            onSubmit={(data) => {
              if (data.kind !== "message") return;
              setMessages((current) => [
                ...current,
                {
                  id: crypto.randomUUID(),
                  role: "user",
                  text: data.text,
                },
                {
                  id: crypto.randomUUID(),
                  role: "assistant",
                  text: "This demo only echoes the UI flow. Wire `Composer` to your AI SDK chat handler for streaming responses.",
                },
              ]);
            }}
          >
            <Composer.Container>
              <Composer.Textarea>
                <Composer.Placeholder placeholder="Message Intentface..." />
              </Composer.Textarea>
              <Composer.Actions>
                <Composer.Submit />
              </Composer.Actions>
            </Composer.Container>
          </Composer>
        </Thread.Composer>
        <Thread.ScrollButton />
      </Thread>
    </div>
  );
};
